الخضراوات وأشجار الفاكهة. أوضح والدها أن النباتات تحتاج إلى رعاية مناسبة، ونصحها ألا تقطف الثمار دون إذن. حافظت سارة على نظافة الممرات، وفي طريق العودة كتبت ثلاثة أشياء جديدة تعلمتها في زيارتها.","listeningQuestion":"ماذا فعلت سارة في طريق العودة؟","options":["كتبت ثلاثة أشياء تعلمتها","قطفت ثمارًا دون سؤال","تركت حقائبها في الطريق"],"grade":3,"sourceKind":"independent Dadyoom-authored teacher-guided listening, NOT official textbook/audio","pedagogicalTarget":"cause_and_effect","originalContentVerifiedAgainst":"actual Dadyoom published Grade3 lesson body, not external textbook edition"},"answer":{"correct":"كتبت ثلاثة أشياء تعلمتها"}},{"lessonId":"865f4a83-5290-487f-9c50-2f67eb5e1e92","lessonTitle":"الاستماع: مزرعتي","sourcePage":10,"activity_order":6,"activity_type":"listening","title":"أستنتج الفكرة","section":"listening","prompt":"ما الذي يوضح احترام المزرعة في النص؟","content":{"origin":"DADYOOM_BH_G3_SIX_DISTINCT_LISTENING_STORIES_30_ORIGINAL_20261030","requiresTeacherRead":true,"text":"ذهبت سارة مع والدها إلى مزرعة صغيرة في الصباح. شاهدت صفوفًا من الخضراوات وأشجار الفاكهة. أوضح والدها أن النباتات تحتاج إلى رعاية مناسبة، ونصحها ألا تقطف الثمار دون إذن. حافظت سارة على نظافة الممرات، وفي طريق العودة كتبت ثلاثة أشياء جديدة تعلمتها في زيارتها.","listeningQuestion":"ما الذي يوضح احترام المزرعة في النص؟","options":["رعاية النبات والمحافظة على نظافة المكان","إتلاف الأشجار","رمي المخلفات في الممرات"],"grade":3,"sourceKind":"independent Dadyoom-authored teacher-guided listening, NOT official textbook/audio","pedagogicalTarget":"main_idea","originalContentVerifiedAgainst":"actual Dadyoom published Grade3 lesson body, not external textbook edition"},"answer":{"correct":"رعاية النبات والمحافظة على نظافة المكان"}}]$g3script$::jsonb)
AS t("lessonId" text,"lessonTitle" text,"sourcePage" integer,activity_order integer,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $guard$
DECLARE eligible integer; inserted integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.bh_grade3_six_listening_30)<>30
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.bh_grade3_six_listening_30)<>6
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.bh_grade3_six_listening_30)<>30
 OR EXISTS(SELECT 1 FROM pg_temp.bh_grade3_six_listening_30 t WHERE
  t.activity_type<>'listening' OR t.activity_order NOT BETWEEN 2 AND 6
  OR length(t.prompt)<15 OR length(t.content->>'text')<160
  OR t.content->>'requiresTeacherRead'<>'true'
  OR t.content->>'listeningQuestion'<>t.prompt
  OR t.content ? 'answer' OR t.content ? 'correct'
  OR t.answer IS NULL OR jsonb_array_length(t.content->'options')<>3
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(t.content->'options') v WHERE v=t.answer->>'correct'))
 THEN RAISE EXCEPTION 'Malformed, incomplete or leaking Grade3 listening activities'; END IF;
 SELECT count(DISTINCT l.id) INTO eligible
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_grade3_six_listening_30 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE l.status='published' AND co.code='BH' AND g.grade_number=3 AND l.source_pdf_url IS NOT NULL
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=1
 AND (SELECT max(a.activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=1
 AND l.content LIKE '%نص%أصلي%'
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 IF eligible<>6 THEN RAISE EXCEPTION 'Grade3 listening lesson scope changed: % / 6',eligible; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_BH_G3_SIX_DISTINCT_LISTENING_STORIES_30_ORIGINAL_20261030')
 THEN RAISE EXCEPTION 'Batch already present; no duplicate append'; END IF;
 INSERT INTO public.lesson_activities
 (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'استمع للنص الأصلي الجديد بصوت المعلم ثم أجب؛ النص ليس من التسجيل الوزاري.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_grade3_six_listening_30 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE l.status='published' AND g.grade_number=3 AND co.code='BH'
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>30 THEN RAISE EXCEPTION 'Atomic rollback: got % Grade3 exercises instead of 30',inserted; END IF;
END $guard$;
COMMIT;